#' Data observed at an analysis cutoff
#'
#' @description
#' Restricts data generated by \code{\link{rOncoEndpoints}} to patients
#' enrolled before an analysis cutoff (calendar time) and censors PFS and OS at
#' the cutoff. A response counts as observed when the patient responded and the
#' response was determined before the cutoff, before dropout and before the
#' censoring of PFS.
#'
#' @details
#' The time at which a response is determined is the time to response when it
#' was generated (\code{resp.timing = "ttr"} in \code{\link{OncoArm}}), the
#' landmark \code{resp.tau}, the time of the first tumor assessment, with
#' \code{resp.timing = "landmark"}, and the time of randomization with
#' \code{resp.timing = "none"}, so that the response of every enrolled patient
#' is then observed. Patients without an observed response have
#' \code{response_obs = 0}, as in an intention-to-treat analysis in which
#' patients without an assessment count as non-responders.
#' \code{response_eval} indicates whether the patient was followed up to the
#' first tumor assessment \code{resp.tau} (\code{NA} when \code{resp.tau} is
#' 0), for analyses restricted to patients with an assessment.
#'
#' For groups without an endpoint, its columns remain \code{NA}.
#'
#' Data generated by version 0.2.0 of the package have no columns
#' \code{resp_tau} and \code{pfs_cens_time}; they are treated as having no
#' landmark and no censoring of PFS.
#'
#' @param data A data frame returned by \code{\link{rOncoEndpoints}}.
#' @param cutoff Calendar time of the cutoff: a scalar, or one value per
#'   simulated trial in \code{data}, in increasing order of \code{sim} (as
#'   returned by \code{\link{EventTime}}). \code{NA} means no cutoff.
#' @return The rows of \code{data} with \code{accrual_time < cutoff}, with
#'   \code{pfs_tte}, \code{pfs_event}, \code{os_tte}, \code{os_event},
#'   \code{pfs_calendar_time} and \code{os_calendar_time} recomputed, and the
#'   added columns \code{response_obs}, \code{response_eval} and
#'   \code{cutoff}.
#' @examples
#' arm <- OncoArm(pfs.median = 6, orr = 0.3, resp.cor = 0.4, death.prop = 0.15,
#'                os.median = 15, resp.timing = "ttr", resp.tau = 1.5,
#'                ttr.median = 2.5)
#' dat <- rOncoEndpoints(nsim = 2, n = 100, arms = arm, a.time = c(0, 12),
#'                       seed = 1)
#' cut <- CutoffData(dat, cutoff = 9)
#' table(cut$sim, cut$response_obs)
#' @export
CutoffData <- function(data, cutoff) {
  req <- c("sim", "accrual_time", "pfs_time", "os_time", "response", "ttr",
           "dropout_time")
  if (!is.data.frame(data) || !all(req %in% names(data))) {
    stop("'data' must be a data frame returned by rOncoEndpoints().", call. = FALSE)
  }
  sims <- sort(unique(data$sim))
  if (length(cutoff) == 1L) {
    cut <- rep(as.numeric(cutoff), nrow(data))
  } else if (length(cutoff) == length(sims)) {
    cut <- as.numeric(cutoff)[match(data$sim, sims)]
  } else {
    stop("'cutoff' must be a scalar or have one value per simulated trial.", call. = FALSE)
  }
  cut[is.na(cut)] <- Inf
  keep <- data$accrual_time < cut
  d <- data[keep, , drop = FALSE]
  cut <- cut[keep]
  tau <- if ("resp_tau" %in% names(d)) d$resp_tau else rep(0, nrow(d))
  pfs_cens <- if ("pfs_cens_time" %in% names(d)) d$pfs_cens_time else rep(Inf, nrow(d))
  # end of follow-up of OS (dropout) and of PFS and response (dropout or
  # censoring of PFS)
  fu_os <- d$dropout_time
  fu_pfs <- pmin(d$dropout_time, pfs_cens)
  # events are compared on the calendar scale so that a cutoff returned by
  # EventTime() counts the event that defines it
  observed <- function(x, fu) x <= fu & d$accrual_time + x <= cut
  ev_pfs <- observed(d$pfs_time, fu_pfs)
  ev_os <- observed(d$os_time, fu_os)
  d$pfs_tte <- ifelse(ev_pfs, d$pfs_time, pmin(fu_pfs, cut - d$accrual_time))
  d$pfs_event <- as.integer(ev_pfs)
  d$os_tte <- ifelse(ev_os, d$os_time, pmin(fu_os, cut - d$accrual_time))
  d$os_event <- as.integer(ev_os)
  d$pfs_calendar_time <- d$accrual_time + d$pfs_tte
  d$os_calendar_time <- d$accrual_time + d$os_tte
  # time at which the response is determined: time to response, landmark, or
  # randomization
  resp_time <- ifelse(is.na(d$ttr), tau, d$ttr)
  d$response_obs <- ifelse(is.na(d$response), NA_integer_,
                           as.integer(d$response == 1 & observed(resp_time, fu_pfs)))
  d$response_eval <- ifelse(tau > 0, as.integer(observed(tau, fu_pfs)), NA_integer_)
  d$cutoff <- cut
  rownames(d) <- NULL
  d
}
